<?php
declare(strict_types=1);
namespace Commerce\Composition;

/**
 * Product-page source binding for original Fluent Forms submissions.
 * A short-lived HMAC receipt is generated by the server while rendering the
 * existing product form; it is validated before insertion and captured through
 * SubmissionContext's current trusted-PHP-only filter.
 */
final class ProductFormSourceReceipt
{
    private static array $inRequest=[];
    private static function allowed(int $formId):bool
    {
        $c=get_option('commerce_inquiry_snapshot_policy_v1',[]);
        return is_array($c)&&($c['enabled']??null)===true
            &&($c['site_url']??null)===home_url()
            &&in_array($formId,array_map('intval',(array)($c['form_ids']??[])),true);
    }
    private static function source():array|\WP_Error
    {
        $context=apply_filters('commerce_composition_render_context',null);
        if($context===null){
            $parent=(int)get_queried_object_id();
            $rate=isset($_GET['rate_id'])&&is_scalar($_GET['rate_id'])
                ?absint(wp_unslash($_GET['rate_id'])):0;
        }else{
            if(!is_array($context))return new \WP_Error('product_form_context_invalid');
            $parent=(int)($context['parent_id']??0);
            $rate=(int)($context['rate_id']??0);
        }
        if($parent<1||!get_post($parent))return new \WP_Error('product_page_source_missing');
        if($rate>0){
            $identity=NativeOrderItemIdentityResolver::source($rate);
            if(is_wp_error($identity)||($identity['parent']??0)!==$parent)
                return new \WP_Error('product_page_rate_parent_invalid');
        }
        return ['parent_id'=>$parent,'rate_id'=>$rate?:null];
    }
    private static function makeToken(int $formId,int $parent,?int $rate,int $expires):string
    {
        $payload=wp_json_encode([1,$formId,$parent,$rate??0,$expires,home_url()],
            JSON_UNESCAPED_SLASHES);
        $part=rtrim(strtr(base64_encode($payload),'+/','-_'),'=');
        $signature=hash_hmac('sha256','commerce-product-page:v1:'.$part,
            wp_salt('secure_auth'));
        return $part.'.'.$signature;
    }
    private static function decodeToken(string $token,int $formId):array|\WP_Error
    {
        if(strlen($token)>850||!preg_match('/^[A-Za-z0-9_-]{20,700}\.[a-f0-9]{64}$/D',$token))
            return new \WP_Error('product_form_receipt_invalid');
        [$body,$signature]=explode('.',$token,2);
        $expected=hash_hmac('sha256','commerce-product-page:v1:'.$body,
            wp_salt('secure_auth'));
        if(!hash_equals($expected,$signature))
            return new \WP_Error('product_form_receipt_signature_invalid');
        $json=base64_decode(strtr($body,'-_','+/'),true);
        $parts=is_string($json)?json_decode($json,true):null;
        if(!is_array($parts)||count($parts)!==6||$parts[0]!==1
            ||!is_int($parts[1])||$parts[1]!==$formId
            ||!is_int($parts[2])||$parts[2]<1
            ||!is_int($parts[3])||$parts[3]<0
            ||!is_int($parts[4])||$parts[4]<time()
            ||$parts[4]>time()+7200
            ||$parts[5]!==home_url())
            return new \WP_Error('product_form_receipt_expired_or_mismatched');
        $parent=$parts[2];$rate=$parts[3]?:null;
        $descriptor=FormRouter::describe($parent,$rate);
        if(is_wp_error($descriptor)||
            !$descriptor['booking_available']||
            ($descriptor['booking_form_id']??null)!==$formId)
            return new \WP_Error('product_form_policy_no_longer_approved');
        if($rate!==null){
            $identity=NativeOrderItemIdentityResolver::source($rate);
            if(is_wp_error($identity)||($identity['parent']??0)!==$parent)
                return new \WP_Error('product_form_rate_not_verified');
        }
        return ['parent_id'=>$parent,'rate_id'=>$rate];
    }
    public static function render($form):void
    {
        if(!is_object($form)||!is_numeric($form->id??null))return;
        $id=(int)$form->id;
        if(!self::allowed($id))return;
        $source=self::source();
        if(is_wp_error($source))return;
        $descriptor=FormRouter::describe(
            $source['parent_id'],$source['rate_id']);
        if(is_wp_error($descriptor)||!$descriptor['booking_available']||
           $descriptor['booking_form_id']!==$id)return;
        $token=self::makeToken($id,$source['parent_id'],$source['rate_id'],time()+3600);
        echo '<input type="hidden" name="_commerce_product_origin" value="'.
            esc_attr($token).'" autocomplete="off" />';
    }
    public static function beforeInsert($insertData,$formData,$form):void
    {
        if(!is_object($form)||!is_numeric($form->id??null)
            ||!is_array($formData))return;
        $id=(int)$form->id;
        if(!self::allowed($id))return;
        // Never reuse a prior valid receipt after an invalid later submission
        // in the same PHP request.
        unset(self::$inRequest[$id]);
        $token=$formData['_commerce_product_origin']??null;
        if(!is_string($token))return;
        $context=self::decodeToken($token,$id);
        if(is_wp_error($context)){
            do_action('commerce_composition_product_source_receipt_rejected',
                $context->get_error_code(),$id);
            return;
        }
        self::$inRequest[$id]=$context;
    }
    public static function trusted($previous,$submissionId,$formId)
    {
        if($previous!==null)return $previous;
        return is_numeric($formId)?(self::$inRequest[(int)$formId]??null):null;
    }
    public static function bootstrap():void
    {
        add_action('fluentform/form_element_start',[self::class,'render'],15,1);
        add_action('fluentform/before_insert_submission',[self::class,'beforeInsert'],15,3);
        add_filter('commerce_composition_trusted_submission_context',
            [self::class,'trusted'],12,3);
    }
}
